    int digitSum(String str) {
        int sum = 0;
        String[] strArr = str.split("");
        for (int i = 0; i < str.length(); ++i) {
            sum += Integer.parseInt(strArr[i]);
        }
        return sum;
    }

    boolean isFin(String str) {
        return str.equals("0");
    }
}

