import java.io.*;
import java.util.*;

public class Main {

	void submit() {
	    int N = nextInt();
        int[] param = new int[3];
        int g = 0;
        long sum = 0;

        for(int i=1; i<=N; i++){
            param[0] = i;
            for(int j=1; j<=N; j++){
                param[1] = j;
                for(int k=1; k<=N; k++){
                    param[2] = k;
                    g = gcd(param[0], param[1]);
                    g = gcd(g, param[1]);
                    g = gcd(g, param[2]);
                    sum += g;
                }
            }
        }
        out.println(sum);
    }

    public static final int gcd(int a, int b) {
        //a > b にする（スワップ）
