	static int gcd2(int x, int y) {
		if(x%y == 0) return y;
		else if(x < y) return gcd2(y, x);
		else return gcd2(y, x%y);
	}

	static int gcd3(int x, int y, int z) {
		int w = gcd2(x, y);
		return gcd2(w, z);
	}

