            trans (S, alp, alp.substring (N) + alp.substring (0, N)));
        return;
    }

    static String trans (String S, String f, String t) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < S.length(); i++) {
            int idx = f.indexOf (S.charAt (i));
            sb.append (t.charAt (idx));
        }
        return sb.toString();
    }
}

