    static class BKThCommonDivisor {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int a = in.nextInt();
            int b = in.nextInt();
            int k = in.nextInt();
            ArrayList<Integer> array = new ArrayList<>();
            int gcd = 1;
            int index = 0;
            for (int i = 1; i <= a && i <= b; ++i) {
