    private static int getMinCost(int[] h, int k) {
        int[] cost = new int[h.length];

        for (int i = 1; i < h.length; i++) {
            cost[i] = Integer.MAX_VALUE;
            for(int j = k; j > 0; j--) {
                if(i-j < 0) continue;
                cost[i] = Math.min(cost[i], cost[i-j] + Math.abs(h[i] - h[i-j]));
            }
        }

        return cost[h.length-1];
    }
