					int sumYen = 10000 * x + 5000 * y + 1000 * z;
					if (sumYen == correctYen) {
							System.out.print(String.valueOf(x) + " " + String.valueOf(y) + " " + String.valueOf(z));
							return;
					}
				}
			}
